  float orthogonal_residual = 0.0f;

  for (int inner_base = 0; inner_base < n; inner_base += kInner) {
    for (int index = tid; index < kRows * kInner; index += kThreads) {
      const int tile_row = index / kInner;
      const int tile_column = index - tile_row * kInner;
      const int input_row = row_base + tile_row;
      const int inner = inner_base + tile_column;
      input_tile[tile_row][tile_column] =
          input_row < n && inner < n
          ? input[matrix_offset + input_row * n + inner]
          : 0.0f;

      const int vector_tile_row = index / kRows;
      const int vector_tile_column = index - vector_tile_row * kRows;
      const int vector_inner = inner_base + vector_tile_row;
      const int vector_column = row_base + vector_tile_column;
      vector_i_tile[vector_tile_row][vector_tile_column] =
          vector_inner < n && vector_column < n
