def _dense_to_band_eigh(data: torch.Tensor, block: int):
    """Blocked two-sided reduction with compact-WY GEMM updates."""
    n = data.shape[-1]
    band = data.clone()
    reflectors = []

    for panel_start in range(0, n - 2 * block, block):
        tail = panel_start + block
        panel = band[:, tail:, panel_start : panel_start + block].contiguous()
        qr, tau = torch.geqrf(panel)
        v, t = _compact_wy(qr, tau)

        band[:, tail:, :] = _apply_wy_left(
            band[:, tail:, :], v, t, transpose=True
        )
        band[:, :, tail:] = _apply_wy_left(
            band[:, :, tail:].transpose(1, 2), v, t, transpose=True
        ).transpose(1, 2)
        reflectors.append((tail, v, t))

    vectors, values, flags = _ext.band_eigh(band)
    vectors = vectors.contiguous()
    for tail, v, t in reversed(reflectors):
        vectors[:, tail:, :] = _apply_wy_left(
            vectors[:, tail:, :], v, t, transpose=False
        )
    return vectors, values, flags


def _guarded_dense_eigh(data: torch.Tensor):
    vectors, values, flags = _dense_to_band_eigh(data, 88)
    if bool(flags[-1]):
        unsafe = flags[:-1].bool()
        safe_vectors, safe_values = _ext.xsyev_batched(data[unsafe])
        vectors[unsafe] = safe_vectors
        values[unsafe] = safe_values
    return vectors, values


def custom_kernel(data: input_t) -> output_t:
    if data.shape[-1] == 32:
        vectors, values = _ext.syevj_batched(data, 3.5e-4, 6)
    elif data.shape[-1] == 176:
        vectors, values = _guarded_dense_eigh(data)
    else:
        vectors, values = _ext.xsyev_batched(data)
    return vectors, values

